mapper.select:
select p.summary_id as summaryId, p.`year`, p.`month`, p.employee_id as employeeId, p.employee_name as employeeName, p.department, p.positive_attendance as actualAttendance, p.probation_attendance as accruedAttendance, case when e.affiliation_system = 2 and e.rest_type = 2 then p.work_over_time else 0 end as workOverTime, case when e.affiliation_system = 2 and e.rest_type = 2 then p.overtime_pay else 0 end as overtimePay, p.empty_class as emptyClass, p.middle_class as middleClass, case when e.affiliation_system = 2 and e.rest_type = 2 then p.night_shift else 0 end as nightShift, case when e.affiliation_system = 2 and e.rest_type = 2 then p.night_subsidy else 0 end as nightSubsidy, p.current_month_vacation as currentMonthVacation, p.loan, p.other_subsidies as otherSubsidies, p.other_deductions as otherDeductions, p.remark from hrm_produce_attendance p left join hrm_employee e on p.employee_id = e.employee_id where 1=1
AND p.employee_Name = #{data.employeeName}
AND p.year = #{data.year}
AND p.month = #{data.month}
AND p.department = #{data.department}
AND e.dept_id in
#{deptId}

select emp_id as employeeId, sum(CASE WHEN field_name in ('旷工天数','旷工迟到天数') THEN value ELSE 0 END) as absenteeismDays, sum(CASE WHEN field_name = '迟到次数' THEN value ELSE 0 END) as lateCount, sum(CASE WHEN field_name = '早退次数' THEN value ELSE 0 END) as earlyCount, sum(CASE WHEN field_name = '上班缺卡次数' THEN value ELSE 0 END) as onDutyMissingCardCount, sum(CASE WHEN field_name = '下班缺卡次数' THEN value ELSE 0 END) as offDutyMissingCardCount from hrm_attendance_report_data where work_date between #{beginDate} and #{endDate}
and emp_id in
#{employeeId}
group by emp_id
